using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using MistWorms.Render.Gpu;
using UnityEditor;
using UnityEngine;
using Debug = UnityEngine.Debug;

/// <summary>
/// Check of the GPU worm simulation in the editor (D3D11 on the dev machine, no -nographics): the real WormSim.compute and the real GpuWormHost of the mod
/// (copied into Assets/Editor/Generated by tools/build-shaders.ps1, with the CPU reference), without the game.
///   1. parity: 64 worms, 30 steps, GPU read back against WormSimRef (tolerance 1 mm), on a slope with a box, a capsule and a sphere;
///   2. a mass of 2000 worms (50 game units x 4) at rest on flat ground: no node under the ground, lengths kept, time per step;
///   3. engulfing a capsule of 1.8 m with 500 and with 2000 worms: coverage by bands of the height;
///   4. pictures of the three levels of detail (Logs/simcheck_*.png), Deferred, with a light.
/// Run: Unity.exe -batchmode -quit -projectPath ... -executeMethod SimCheck.Run (without -nographics). Exit code 1 when a check fails.
/// </summary>
public static class SimCheck
{
    private static int s_failures;

    public static void Run()
    {
        try
        {
            Go();
            EditorApplication.Exit(s_failures == 0 ? 0 : 1);
        }
        catch (Exception e)
        {
            Debug.LogError("SimCheck: FAILED " + e);
            EditorApplication.Exit(1);
        }
    }

    private static void Check(string name, bool ok, string detail)
    {
        Debug.Log($"SimCheck: {(ok ? "PASS" : "FAIL")} {name}: {detail}");
        if (!ok) s_failures++;
    }

    private static void Go()
    {
        var compute = AssetDatabase.LoadAssetAtPath<ComputeShader>("Assets/Shaders/WormSim.compute");
        var ropeMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WormRope.mat");
        if (compute == null || ropeMat == null) throw new Exception("WormSim.compute or WormRope.mat missing: run BuildBundles first");
        Debug.Log($"SimCheck: api={SystemInfo.graphicsDeviceType} compute={SystemInfo.supportsComputeShaders} rope supported={ropeMat.shader.isSupported}");
        GpuWormHost.Log = s => Debug.Log(s);
        GpuWormHost.LogWarning = s => Debug.LogWarning(s);
        if (!GpuWormHost.TryInit(new GpuWormAssets { Compute = compute, RopeMaterial = ropeMat }, false))
            throw new Exception("host init failed: " + GpuWormHost.Error);
        GpuWormHost.AutoStep = false;

        // MW_SIMCHECK_ONLY=skin: only the skin engulf (the formation of the sleeve), for the quick loop on the entry of the worms
        if (Environment.GetEnvironmentVariable("MW_SIMCHECK_ONLY") == "skin")
        {
            SkinBody(500);
            SkinBody(2000);
            GpuWormHost.Shutdown();
            return;
        }

        Parity();
        Rest();
        BirthAndDeath();
        Engulf(500, 1.0f, "n50");
        Engulf(2000, 1.0f, "n200");
        EngulfBody(2000);
        Drape(2000);
        foreach (int w in new[] { 500, 2000 })
        {
            Cross(w, false);
            Cross(w, true);
        }
        SkinSimParity();
        SkinCpuCost();
        SkinBody(500);
        SkinBody(2000);
        FreeWorms();
        Pictures();
        GpuWormHost.Shutdown();
    }

    // ------------------------------------------------------------------ 1. parity

    private static void Parity()
    {
        ParityRun(0.30f, GpuMassMode.Engulf, false);    // dense and in contact with an adhesive capsule: chaotic (jammed worms amplify the rounding of the GPU), reported only
        ParityRun(2.20f, GpuMassMode.Dome, true);       // the seed of the scenario: 64 worms with room, a box, a capsule and a sphere in the dome, compared with a millimetre
    }

    private static void ParityRun(float radius, GpuMassMode mode, bool assert)
    {
        float k = 3.333f;
        GpuWormHost.ResetStepIndex();
        Vector3 world = new Vector3(2543.37f, 31.2f, -1807.61f);       // far from the origin, as in the game
        GpuMass m = GpuWormHost.CreateMass(64, world, radius, 77u);
        m.ForceSimulated = true;
        if (assert) m.DomeHeight = 0.02f;
        m.Heading = new Vector3(0.6f, 0f, 0.8f);
        m.Speed = 0.6f;
        // slope and a bump
        int hn = WormSimConst.HeightN;
        float ext = m.GridExtent, sp = ext / (hn - 1);
        Vector2 min = new Vector2(world.x - ext * 0.5f, world.z - ext * 0.5f);
        for (int z = 0; z < hn; z++)
            for (int x = 0; x < hn; x++)
            {
                float wx = min.x + x * sp - m.Origin.x, wz = min.y + z * sp - m.Origin.z;
                m.Heights[z * hn + x] = 0.08f * wx + 0.03f * Mathf.Sin(wz * 5f);
            }
        m.Mode = mode;
        m.Engulf = 0.6f;
        m.AdhesivePrim = 1;
        m.Prims[0] = GpuPrim.Box(new Vector3(0.35f * k, 0.15f, 0.0f), new Vector3(0.15f, 0.2f, 0.12f), Quaternion.Euler(0f, 30f, 0f));
        m.Prims[1] = GpuPrim.Capsule(new Vector3(-0.1f * k, 0.3f, 0.1f * k), new Vector3(-0.1f * k, 1.2f, 0.1f * k), 0.12f, 1f, 0.6f);
        m.Prims[2] = GpuPrim.Sphere(new Vector3(0.0f, 0.1f, -0.4f * k), 0.1f);
        m.SideYMin = world.y - 0.5f;
        m.SideYStep = 0.3f;
        m.SideEnabled = true;
        {
            // depth maps of a block in the dome (local frame), as the capture would give them
            var floats = new float[WormSimConst.SideMaps * WormSimConst.SideMapSize];
            GpuMassParams pp = GpuWormHost.BuildParams(m, true);
            pp.GridRect = new Vector4(min.x - m.Origin.x, min.y - m.Origin.z, sp, 1f / sp);
            GpuSolidMaps.FillBox(floats, 0, pp, new Vector3(0.9f, 0f, -0.3f), new Vector3(1.5f, 0.7f, 0.3f));
            for (int i = 0; i < floats.Length; i++) m.Sides[i] = floats[i];
        }
        GpuWormHost.UploadEnvironment(m, 3, min, sp);
        GpuWormHost.InitNow(m);

        var r = new WormSimRef(64);
        r.Masses[0] = GpuWormHost.BuildParams(m, true);
        for (int i = 0; i < Mathf.Min(r.Height.Length, m.Heights.Length); i++) r.Height[i] = m.Heights[i];
        for (int i = 0; i < 3; i++) r.Prims[i] = m.Prims[i];
        for (int i = 0; i < m.Sides.Length; i++) r.Sides[i] = m.Sides[i];
        for (int i = 0; i < 64; i++) r.Worms[i] = WormSimRef.MakeWorm(0u, WormSimRef.Hash(unchecked(77u * 0x9E3779B1u + (uint)i)));
        r.Init(0, 64);
        r.StepIndex = GpuWormHost.StepIndex;
        // The init is compared on its own (sin and cos of the GPU differ from the CPU by a few 1e-7); the steps start from the very same nodes, so that only the
        // arithmetic of the steps is compared (the rope dynamics amplify a difference of the start).
        var gpuInit = new Vector4[64 * 8];
        GpuWormHost.PosBuffer.GetData(gpuInit, 0, 0, gpuInit.Length);
        float initDiff = 0f;
        for (int i = 0; i < gpuInit.Length; i++) initDiff = Mathf.Max(initDiff, new Vector3(gpuInit[i].x - r.Pos[i].x, gpuInit[i].y - r.Pos[i].y, gpuInit[i].z - r.Pos[i].z).magnitude);
        for (int i = 0; i < gpuInit.Length; i++) { r.Pos[i] = gpuInit[i]; r.Prev[i] = gpuInit[i]; }
        if (assert) Check("parity_init", initDiff < 1e-3f, $"max difference of the init {initDiff * 1000f:0.0000} mm");

        string tag = $"r{radius:0.0}";
        var gpu = new Vector4[64 * 8];
        int done = 0;
        foreach (int target in new[] { 1, 10, 30 })
        {
            while (done < target) { GpuWormHost.StepNow(1); r.Step(); done++; }
            float d = Compare(r, gpu);
            if (assert) Check($"parity_{target}_steps", d < 1e-3f, $"max difference {d * 1000f:0.0000} mm");
            else Debug.Log($"SimCheck: parity {tag} {target} steps: max difference {d * 1000f:0.0000} mm (reported, not asserted)");
        }

        // determinism: the same 30 steps on the GPU again give exactly the same bits
        var first = (Vector4[])gpu.Clone();
        GpuWormHost.ResetStepIndex();
        GpuWormHost.InitNow(m);
        GpuWormHost.StepNow(30);
        GpuWormHost.PosBuffer.GetData(gpu, 0, 0, gpu.Length);
        float worst = 0f;
        for (int i = 0; i < gpu.Length; i++) worst = Mathf.Max(worst, Mathf.Max(Mathf.Abs(gpu[i].x - first[i].x), Mathf.Max(Mathf.Abs(gpu[i].y - first[i].y), Mathf.Abs(gpu[i].z - first[i].z))));
        Check($"gpu_deterministic_{tag}", worst == 0f, $"largest difference between two GPU runs of 30 steps: {worst}");
        GpuWormHost.RemoveMass(m);
    }

    private static float Compare(WormSimRef r, Vector4[] gpu)
    {
        GpuWormHost.PosBuffer.GetData(gpu, 0, 0, gpu.Length);
        float max = 0f;
        int at = 0;
        for (int i = 0; i < gpu.Length; i++)
        {
            Vector3 a = new Vector3(gpu[i].x, gpu[i].y, gpu[i].z), b = new Vector3(r.Pos[i].x, r.Pos[i].y, r.Pos[i].z);
            if ((a - b).magnitude > max) { max = (a - b).magnitude; at = i; }
        }
        Debug.Log($"SimCheck: worst node worm {at / 8} node {at % 8}: gpu ({gpu[at].x:0.000000},{gpu[at].y:0.000000},{gpu[at].z:0.000000}) ref ({r.Pos[at].x:0.000000},{r.Pos[at].y:0.000000},{r.Pos[at].z:0.000000}) diff {max * 1000f:0.0000} mm");
        return max;
    }

    // The count of the game follows on the GPU: a segment of 300 worms with 100 alive, then 250 (the newborn grow from nothing in 0.5 s), then 100 again (they shrink to nothing).
    private static void BirthAndDeath()
    {
        const int cap = 300;
        GpuMass m = GpuWormHost.CreateMass(100, cap, Vector3.zero, 0.5f, 3u);
        m.Origin = Vector3.zero;
        GpuWormHost.SetFlatEnvironment(m, 0f);
        GpuWormHost.InitNow(m);
        GpuWormHost.Tick(0f);
        GpuWormHost.StepNow(30);
        Vector4[] pos = Read(cap);
        Check("birth_spare_worms_have_no_size", pos[150 * 8 + 3].w == 0f && pos[10 * 8 + 3].w == 1f, $"spare {pos[150 * 8 + 3].w}, alive {pos[10 * 8 + 3].w}");
        GpuWormHost.SetActive(m, 250);
        GpuWormHost.Tick(0f);
        GpuWormHost.StepNow(10);
        pos = Read(cap);
        float mid = pos[200 * 8 + 3].w;
        GpuWormHost.StepNow(40);
        pos = Read(cap);
        Check("birth_grows_in_half_a_second", mid > 0.1f && mid < 0.9f && pos[200 * 8 + 3].w == 1f && pos[280 * 8 + 3].w == 0f, $"newborn after 10 steps {mid:0.00}, after 50 {pos[200 * 8 + 3].w:0.00}; beyond the count {pos[280 * 8 + 3].w:0.00}");
        GpuWormHost.SetActive(m, 100);
        GpuWormHost.Tick(0f);
        GpuWormHost.StepNow(40);
        pos = Read(cap);
        Check("death_shrinks_to_nothing", pos[200 * 8 + 3].w == 0f && pos[50 * 8 + 3].w == 1f && CountNan(pos) == 0, $"absorbed {pos[200 * 8 + 3].w:0.00}, alive {pos[50 * 8 + 3].w:0.00}");
        GpuWormHost.RemoveMass(m);
    }

    // ------------------------------------------------------------------ 2. rest

    private static GpuMass Spawn(int worms, float radius, uint seed, Vector3 center)
    {
        GpuMass m = GpuWormHost.CreateMass(worms, center, radius, seed);
        if (m == null) throw new Exception("CreateMass failed");
        m.Origin = Vector3.zero;
        GpuWormHost.SetFlatEnvironment(m, 0f);
        return m;
    }

    private static Vector4[] Read(int worms)
    {
        var a = new Vector4[worms * 8];
        GpuWormHost.PosBuffer.GetData(a, 0, 0, a.Length);
        return a;
    }

    private static void Rest()
    {
        const int worms = 2000;
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 5u, Vector3.zero);
        GpuWormHost.InitNow(m);
        var sw = Stopwatch.StartNew();
        GpuWormHost.StepNow(10);
        Read(worms);
        sw.Restart();
        GpuWormHost.StepNow(300);
        Vector4[] pos = Read(worms);
        double msPerStep = sw.Elapsed.TotalMilliseconds / 300.0;
        float minY = float.MaxValue, maxLenDev = 0f, maxR = 0f;
        for (int w = 0; w < worms; w++)
        {
            for (int i = 0; i < 8; i++)
            {
                Vector4 p = pos[w * 8 + i];
                minY = Mathf.Min(minY, p.y);
                maxR = Mathf.Max(maxR, new Vector2(p.x, p.z).magnitude);
                if (i < 7)
                {
                    Vector4 q = pos[w * 8 + i + 1];
                    maxLenDev = Mathf.Max(maxLenDev, Mathf.Abs(new Vector3(q.x - p.x, q.y - p.y, q.z - p.z).magnitude / WormSimConst.SegLen - 1f));
                }
            }
        }
        Check("rest_no_node_under_ground", minY >= WormSimConst.Radius - 1e-4f, $"lowest node {minY * 1000f:0.0} mm (limit {WormSimConst.Radius * 1000f:0.0})");
        Check("rest_lengths_kept", maxLenDev < 0.08f, $"largest segment error {maxLenDev * 100f:0.0} % over 300 steps");
        Check("rest_inside_dome", maxR < r * 1.5f, $"largest horizontal radius {maxR:0.00} m (dome {r:0.00})");
        {
            var heights = new List<float>();
            var radii = new List<float>();
            foreach (Vector4 p in pos) { heights.Add(p.y); radii.Add(new Vector2(p.x, p.z).magnitude); }
            heights.Sort(); radii.Sort();
            float top = heights[heights.Count - 1], median = heights[heights.Count / 2], r90 = radii[(int)(radii.Count * 0.9f)];
            Debug.Log($"SimCheck: rest volume: highest node {top:0.00} m ({top / r:0.00} r), median height {median:0.00} m, 90% of the nodes within {r90:0.00} m ({r90 / r:0.00} r)");
            Check("rest_volume_height", top >= 0.30f * r, $"highest node {top:0.00} m, required >= {0.30f * r:0.00} (0.30 r)");
            Check("rest_volume_extent", r90 <= 1.3f * r, $"90% of the nodes within {r90:0.00} m, required <= {1.3f * r:0.00} (1.3 r)");
        }
        Debug.Log($"SimCheck: rest {worms} worms: {msPerStep:0.000} ms per step (4 dispatches + synchronous readback every 300 steps), dome radius {r:0.00} m");
        Picture("rest", m, 1.2f, 0.5f, 0.2f);
        GpuWormHost.RemoveMass(m);
    }

    // ------------------------------------------------------------------ 3. engulf

    private static void Engulf(int worms, float engulf, string tag)
    {
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 9u, Vector3.zero);
        const float cr = 0.3f, height = 1.8f;
        m.Prims[0] = GpuPrim.Capsule(new Vector3(0f, cr, 0f), new Vector3(0f, height - cr, 0f), cr, 1f, engulf);
        m.Mode = GpuMassMode.Engulf;
        m.Engulf = engulf;
        m.AdhesivePrim = 0;
        m.ShellThickness = 0.02f;
        GpuWormHost.UploadEnvironment(m, 1, new Vector2(-m.GridExtent * 0.5f, -m.GridExtent * 0.5f), m.GridExtent / (WormSimConst.HeightN - 1));
        GpuWormHost.InitNow(m);
        Debug.Log($"SimCheck: engulf {tag} init: {CountNan(Read(worms))} NaN nodes");
        int[] marks = { 1, 3, 10, 40, 120, 300, 600 };
        int done = 0;
        foreach (int target in marks)
        {
            GpuWormHost.StepNow(target - done);
            done = target;
            Vector4[] pos = Read(worms);
            int nan = CountNan(pos);
            if (nan > 0) { Debug.Log($"SimCheck: engulf {tag} after {target} steps: {nan} NaN nodes"); continue; }
            float cover = Coverage(pos, worms, cr, height, m.ShellThickness, out float topY, out int attachedNodes);
            Debug.Log($"SimCheck: engulf {tag} after {target} steps: coverage {cover * 100f:0}% of the height, highest attached node {topY:0.00} m, {attachedNodes} nodes within the shell (shell {m.ShellThickness * 100f:0.0} cm)");
            if (target == marks[marks.Length - 1])
            {
                Check($"engulf_{tag}_coverage", cover >= 0.6f * engulf, $"coverage {cover * 100f:0}% (required {60f * engulf:0}%)");
                SurfaceStats(pos, worms, cr, height, out float area, out float up, out float flat, out float layers);
                Check($"engulf_{tag}_area_coverage", area >= 0.6f && area <= 0.92f, $"{area * 100f:0}% of the surface cells (12 x 12) have a worm within 3 cm; wanted 70 to 85%");
                Check($"engulf_{tag}_climbing", up >= 0.55f && flat <= 0.3f, $"{up * 100f:0}% of the worms on the body point up or diagonally, {flat * 100f:0}% lie flat across");
                Check($"engulf_{tag}_thin_layer", layers <= 2.2f, $"{layers:0.0} nodes of thickness over the covered cells (1 to 2 wanted)");
            }
        }
        var cap = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        cap.transform.localScale = new Vector3(0.6f, 0.9f, 0.6f);
        cap.transform.position = new Vector3(0f, 0.9f, 0f);
        Picture("engulf_" + tag, m, 1.6f, 0.9f, 0.5f);
        UnityEngine.Object.DestroyImmediate(cap);
        {
            Vector4[] pos = Read(worms);
            var sb = new System.Text.StringBuilder("SimCheck: worm 0 nodes");
            for (int i = 0; i < 8; i++) sb.Append($" ({pos[i].x:0.000},{pos[i].y:0.000},{pos[i].z:0.000})");
            Debug.Log(sb.ToString());
        }
        GpuWormHost.RemoveMass(m);
    }

    // The skin engulf on a synthetic body (eight capsules sampled as a mesh would be, one bone per limb): the anchors are skinned by the compute shader from the matrices of the bones
    // (checked against the CPU), the engulf rises from 0 to 1 and the worms climb the body from its base, then lie on its surface along their whole length, up or diagonally. Then
    // the body moves (the legs and the arms swing, the matrices of the bones are uploaded every 8 steps as the game does every frame) and the worms must follow.
    private static void SkinBody(int worms)
    {
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 41u, Vector3.zero);
        var limbs = new int[WormSimConst.MaxAnchors];
        GpuSkinSet set = GpuSkinAnchors.SyntheticSkin(Vector3.zero, 1.75f, limbs);
        set.Area = 2.84f;       // the surface of the real player in game (the anchors are 8 cm apart there)
        var region = new int[WormSimConst.MaxAnchors];
        for (int a = 0; a < set.Count; a++) region[a] = GpuSkinMetrics.RegionOfLimb(limbs[a]);
        Matrix4x4[] bones = GpuSkinAnchors.RestBones();
        GpuWormHost.UploadSkin(m, set);
        GpuWormHost.UploadBones(m, bones, set.BoneCount);
        m.AnchorCount = set.Count;
        m.TargetHeight = 1.75f;
        m.SurfaceArea = set.Area;
        m.Mode = GpuMassMode.Engulf;
        m.Engulf = 0f;
        GpuWormHost.InitNow(m);
        Debug.Log($"SimCheck: skin body: {set.Count} anchors, area {set.Area:0.00} m2, {worms} worms, {set.BoneCount} bones, {set.BaseCount} anchors at the base");

        SkinKernelParity(m, set, bones);

        // the engulf rises from 0 to 1 in 0.5 s (8 steps per frame)
        var timeline = new System.Text.StringBuilder();
        int formed = 0;
        for (int step = 0; step < 240; step += 8)
        {
            m.Engulf = Mathf.Min(1f, step / 30f);
            GpuWormHost.Tick(0f);
            GpuWormHost.StepNow(8);
            if (step == 152) { SkinSnapshot(m, region, worms, set.Count, out GpuSkinMetrics.Result f25); formed = f25.Settled; }
            if (step % 24 == 0 || step == 232)
            {
                SkinSnapshot(m, region, worms, set.Count, out GpuSkinMetrics.Result q);
                timeline.Append($" t={step / 60f:0.0}s engulf {m.Engulf:0.00}: S {m.SleevePlan.Count:0}, transit {q.Transit}, settled {q.Settled};");
            }
        }
        Debug.Log($"SimCheck: skin timeline ({worms} worms):" + timeline);
        m.Engulf = 1f;
        for (int step = 0; step < 480; step += 8)
        {
            GpuWormHost.Tick(0f);
            GpuWormHost.StepNow(8);
        }
        SkinReport("still", m, region, worms, set, true, formed);
        Picture("skin_body", m, 2.4f, 1.0f, 0.9f);
        Picture("skin_body_close", m, 1.1f, 1.2f, 1.1f);

        // the body moves: legs swing along z, arms swing along z, the whole body goes forward by 0.6 m/s
        for (int step = 0; step < 360; step += 8)
        {
            float tt = step / 60f;
            for (int b = 0; b < 8; b++)
            {
                float swing = b >= 2 && b <= 5 ? 0.12f * Mathf.Sin(tt * 4f + (b % 2) * Mathf.PI) : b >= 6 ? 0.15f * Mathf.Sin(tt * 4f + (b % 2) * Mathf.PI + Mathf.PI) : 0f;
                bones[b] = Matrix4x4.Translate(new Vector3(0f, 0f, swing + 0.6f * tt));
            }
            GpuWormHost.UploadBones(m, bones, set.BoneCount);
            m.Center = new Vector3(0f, 0f, 0.6f * tt);
            GpuWormHost.Tick(0f);
            GpuWormHost.StepNow(8);
        }
        SkinReport("moving", m, region, worms, set, false);
        Picture("skin_body_moving", m, 2.4f, 1.0f, 0.9f);
        GpuWormHost.RemoveMass(m);
    }

    // What the CPU does each frame for the skin: the matrices of the 53 bones the anchors use (world matrix times bind pose, relative to the origin of the mass) uploaded to the GPU,
    // on a hierarchy of 53 transforms that move every frame. Budget 0.05 ms per frame, no allocation.
    private static void SkinCpuCost()
    {
        const int bonesCount = 53, frames = 3000;
        var root = new GameObject("SkinCostRoot").transform;
        var t = new Transform[bonesCount];
        var bind = new Matrix4x4[bonesCount];
        var upload = new Matrix4x4[WormSimConst.MaxBones];
        for (int i = 0; i < bonesCount; i++)
        {
            t[i] = new GameObject("b" + i).transform;
            t[i].SetParent(i < 4 ? root : t[(i - 1) / 2], false);
            t[i].localPosition = new Vector3(0.01f * (i % 5), 0.1f, 0.01f * (i % 3));
            t[i].localRotation = Quaternion.Euler(3f * i, 5f, -2f * i);
            bind[i] = t[i].worldToLocalMatrix;
        }
        GpuMass m = Spawn(100, 0.5f, 3u, Vector3.zero);
        m.Origin = new Vector3(2543f, 31f, -1807f);
        Vector3 o = m.Origin;
        for (int warm = 0; warm < 200; warm++) SkinCostFrame(t, bind, upload, m, o, warm);
        long heap0 = UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong();
        long gc0 = System.GC.CollectionCount(0);
        long t0 = Stopwatch.GetTimestamp();
        for (int f = 0; f < frames; f++) SkinCostFrame(t, bind, upload, m, o, f);
        double ms = (Stopwatch.GetTimestamp() - t0) * 1000.0 / Stopwatch.Frequency / frames;
        long rise = UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong() - heap0;
        long gcs = System.GC.CollectionCount(0) - gc0;
        // the transforms moved by the loop itself cost too (the game moves them with the animator): measured here with the loop of the transforms alone, subtracted
        long t1 = Stopwatch.GetTimestamp();
        for (int f = 0; f < frames; f++) MoveBones(t, f);
        double moveMs = (Stopwatch.GetTimestamp() - t1) * 1000.0 / Stopwatch.Frequency / frames;
        Debug.Log($"SimCheck: skin CPU cost: {ms:0.0000} ms per frame for {bonesCount} bones (of which {moveMs:0.0000} ms moving the transforms, done by the animator in the game), heap rise {rise} bytes, {gcs} collections over {frames} frames");
        Check("skin_cpu_cost_budget", ms - moveMs <= 0.05, $"{ms - moveMs:0.0000} ms per frame (budget 0.05 ms)");
        Check("skin_cpu_no_allocation", rise <= 0 && gcs == 0, $"{rise} bytes over {frames} frames, {gcs} collections");
        GpuWormHost.RemoveMass(m);
        UnityEngine.Object.DestroyImmediate(root.gameObject);
    }

    private static void MoveBones(Transform[] t, int f)
    {
        for (int i = 0; i < t.Length; i++) t[i].localRotation = Quaternion.Euler(3f * i + 0.05f * f, 5f, -2f * i);
    }

    private static void SkinCostFrame(Transform[] t, Matrix4x4[] bind, Matrix4x4[] upload, GpuMass m, Vector3 o, int f)
    {
        MoveBones(t, f);
        for (int b = 0; b < t.Length; b++)
        {
            Matrix4x4 mm = t[b].localToWorldMatrix * bind[b];
            mm.m03 -= o.x; mm.m13 -= o.y; mm.m23 -= o.z;
            upload[b] = mm;
        }
        GpuWormHost.UploadBones(m, upload, t.Length);
    }

    // The sleeve against the CPU reference: 200 worms of a mass that engulfs the synthetic body, 60 steps (1 s: the worms enter, climb, settle). The decisions of the sleeve (a head
    // that is at the anchor of its path or not, a mode) are thresholds: a rounding of the GPU that crosses one sends the worm elsewhere and the two runs part for good. So the
    // two are compared step by step, the reference being given the state of the GPU before each step (nodes, previous nodes, modes, anchors of the nodes): what is compared is the
    // arithmetic of one step. Almost every worm must be within a millimetre; a worm at a threshold may part (counted, and reported).
    private static void SkinSimParity()
    {
        const int worms = 200;
        GpuWormHost.ResetStepIndex();
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 77u, Vector3.zero);
        var limbs = new int[WormSimConst.MaxAnchors];
        GpuSkinSet set = GpuSkinAnchors.SyntheticSkin(Vector3.zero, 1.75f, limbs);
        Matrix4x4[] bones = GpuSkinAnchors.RestBones();
        GpuWormHost.UploadSkin(m, set);
        GpuWormHost.UploadBones(m, bones, set.BoneCount);
        m.AnchorCount = set.Count;
        m.TargetHeight = 1.75f;
        m.SurfaceArea = set.Area;
        m.Mode = GpuMassMode.Engulf;
        m.Engulf = 1f;
        GpuWormHost.InitNow(m);

        var rf = new WormSimRef(worms);
        rf.Masses[m.Slot] = GpuWormHost.BuildParams(m, true);
        for (int i = 0; i < WormSimConst.HeightN * WormSimConst.HeightN; i++) rf.Height[m.Slot * WormSimConst.HeightN * WormSimConst.HeightN + i] = m.Heights[i];
        rf.SetSkin(m.Slot, set);
        System.Array.Copy(bones, 0, rf.Bones, m.Slot * WormSimConst.MaxBones, set.BoneCount);
        rf.SkinAnchors(m.Slot);
        for (int i = 0; i < worms; i++) rf.Worms[i] = WormSimRef.MakeWorm((uint)m.Slot, WormSimRef.Hash(unchecked(77u * 0x9E3779B1u + (uint)i)));
        rf.Init(0, worms);

        var pos = new Vector4[worms * 8];
        var prev = new Vector4[worms * 8];
        var state = new Vector4[worms];
        var na = new uint[worms * 8];
        var gpu = new Vector4[worms * 8];
        int apart = 0, wormSteps = 0, steps = 60;
        float worstOk = 0f, worst = 0f;
        for (int s = 0; s < steps; s++)
        {
            GpuWormHost.PosBuffer.GetData(pos, 0, 0, pos.Length);
            GpuWormHost.PrevBuffer.GetData(prev, 0, 0, prev.Length);
            GpuWormHost.SkinStateBuffer.GetData(state, 0, 0, worms);
            GpuWormHost.NodeAnchorBuffer.GetData(na, 0, 0, na.Length);
            for (int i = 0; i < pos.Length; i++) { rf.Pos[i] = pos[i]; rf.Prev[i] = prev[i]; rf.NodeAnchor[i] = na[i]; }
            for (int w = 0; w < worms; w++) rf.SkinState[w] = state[w];
            rf.StepIndex = GpuWormHost.StepIndex;
            GpuWormHost.StepNow(1);
            rf.Step();
            GpuWormHost.PosBuffer.GetData(gpu, 0, 0, gpu.Length);
            for (int w = 0; w < worms; w++)
            {
                float d = 0f;
                for (int i = 0; i < 8; i++) d = Mathf.Max(d, new Vector3(gpu[w * 8 + i].x - rf.Pos[w * 8 + i].x, gpu[w * 8 + i].y - rf.Pos[w * 8 + i].y, gpu[w * 8 + i].z - rf.Pos[w * 8 + i].z).magnitude);
                wormSteps++;
                worst = Mathf.Max(worst, d);
                if (d > 1e-3f) apart++; else worstOk = Mathf.Max(worstOk, d);
            }
        }
        Check("skin_sleeve_parity_step_by_step", apart <= 0.002f * wormSteps, $"{worms} worms, {steps} steps, the reference started from the state of the GPU before each: {apart} of {wormSteps} worm steps beyond 1 mm (worst {worst * 1000f:0.000} mm, worst of the others {worstOk * 1000f:0.0000} mm)");
        GpuWormHost.RemoveMass(m);
    }

    // KSkin against the CPU skinning: random rotations and translations of the bones, a vertex in five on two bones.
    private static void SkinKernelParity(GpuMass m, GpuSkinSet original, Matrix4x4[] restBones)
    {
        GpuSkinSet set = new GpuSkinSet { Count = original.Count, Area = original.Area, BoneCount = original.BoneCount, BaseCount = original.BaseCount };
        System.Array.Copy(original.Verts, set.Verts, original.Count);
        System.Array.Copy(original.Knn, set.Knn, original.Knn.Length);
        System.Array.Copy(original.Order, set.Order, original.Order.Length);
        System.Array.Copy(original.SortedRel, set.SortedRel, original.SortedRel.Length);
        System.Array.Copy(original.Hop, set.Hop, original.Hop.Length);
        for (int i = 0; i < set.Count; i += 5)
        {
            GpuSkinVertex v = set.Verts[i];
            v.Bone1 = (v.Bone0 + 3u) % 8u;
            v.Weights = new Vector4(0.6f, 0.4f, 0f, 0f);
            set.Verts[i] = v;
        }
        var bones = new Matrix4x4[WormSimConst.MaxBones];
        for (int b = 0; b < bones.Length; b++) bones[b] = Matrix4x4.TRS(new Vector3(0.1f * (b % 8), 0.02f * (b % 5), -0.05f * (b % 3)), Quaternion.Euler(10f * (b % 8), 20f, -7f * (b % 8)), Vector3.one);
        GpuWormHost.UploadSkin(m, set);
        GpuWormHost.UploadBones(m, bones, set.BoneCount);
        GpuWormHost.SkinNow();
        var gpu = new GpuAnchor[set.Count];
        GpuWormHost.AnchorsBuffer.GetData(gpu, 0, m.Slot * WormSimConst.MaxAnchors, set.Count);
        var cpu = new GpuAnchor[set.Count];
        GpuSkinning.SkinAll(set, bones, cpu, 0);
        float worstPos = 0f, worstNrm = 0f;
        for (int i = 0; i < set.Count; i++)
        {
            worstPos = Mathf.Max(worstPos, new Vector3(gpu[i].A.x - cpu[i].A.x, gpu[i].A.y - cpu[i].A.y, gpu[i].A.z - cpu[i].A.z).magnitude);
            worstNrm = Mathf.Max(worstNrm, new Vector3(gpu[i].B.x - cpu[i].B.x, gpu[i].B.y - cpu[i].B.y, gpu[i].B.z - cpu[i].B.z).magnitude);
            if (gpu[i].B.w != cpu[i].B.w) worstNrm = 1f;
        }
        Check("skin_kernel_parity", worstPos < 1e-3f && worstNrm < 1e-3f, $"{set.Count} anchors skinned by the GPU and the CPU: position {worstPos * 1000f:0.0000} mm, normal {worstNrm:0.000000}");
        // back to the pose of the selection
        GpuWormHost.UploadSkin(m, original);
        GpuWormHost.UploadBones(m, restBones, original.BoneCount);
        GpuWormHost.SkinNow();
    }

    private static void SkinSnapshot(GpuMass m, int[] region, int worms, int count, out GpuSkinMetrics.Result result)
    {
        Vector4[] pos = Read(worms);
        var state = new Vector4[worms];
        GpuWormHost.SkinStateBuffer.GetData(state, 0, m.FirstWorm, worms);
        var anchors = new GpuAnchor[count];
        GpuWormHost.AnchorsBuffer.GetData(anchors, 0, m.Slot * WormSimConst.MaxAnchors, count);
        result = GpuSkinMetrics.Measure(pos, state, anchors, count, region, worms);
    }

    private static void SkinReport(string tag, GpuMass m, int[] region, int worms, GpuSkinSet set, bool limbChecks, int formed = 0)
    {
        SkinSnapshot(m, region, worms, set.Count, out GpuSkinMetrics.Result r);
        GpuSleevePlan plan = m.SleevePlan;
        Debug.Log($"SimCheck: skin {tag}: S = {plan.Count:0} of {worms} worms ({100f * plan.Count / worms:0}%) over {plan.Cover} of {set.Count} anchors up to {plan.TopRel * 100f:0}% of the height; " +
                  $"pile {r.Pile}, transit {r.Transit}, settled {r.Settled}, falling {r.Falling}; {r.Near} settled worms with 6 nodes of 8 within 4 cm of the skin ({r.NearShare * 100f:0}%); " +
                  $"left leg {r.NearRegion[0]}, right leg {r.NearRegion[1]}, left arm {r.NearRegion[2]}, right arm {r.NearRegion[3]}, torso and head {r.NearRegion[4]}");
        Check($"skin_{tag}_worms_on_the_surface", r.Settled > 50 && r.NearShare >= (limbChecks ? 0.7f : 0.6f), $"{r.NearShare * 100f:0}% of {r.Settled} within 4 cm (>= 70% at rest, 60% while the body moves)");
        if (limbChecks)
        {
            Check("skin_sleeve_size", plan.Count >= 0.4f * worms && plan.Count <= 0.6f * worms + 1e-3f, $"S = {100f * plan.Count / worms:0}% of the worms (surface {set.Area:0.00} m2: 2 layers of 30 x 1.8 cm worms)");
            Check("skin_sleeve_formed_in_2.5s", formed >= 0.9f * r.Settled, $"{formed} worms settled 2.5 s after the start of the engulf, {r.Settled} at the steady state (>= 90%: the game is slower than the editor)");
            Check("skin_sleeve_filled", r.Settled + r.Transit >= 0.5f * plan.Count, $"{r.Settled + r.Transit} worms on the body for S = {plan.Count:0}");
            Check("skin_every_leg", r.NearRegion[0] >= 0.03f * r.Near && r.NearRegion[1] >= 0.03f * r.Near, "a worm on each leg (>= 3%)");
            if (worms >= 2000) Check("skin_every_arm", r.NearRegion[2] >= 0.02f * r.Near && r.NearRegion[3] >= 0.02f * r.Near, "a worm on each arm (>= 2%: an arm is 3 to 6% of the surface of a body)");
        }
    }

    // eight bone capsules like a humanoid (torso, head, thighs, calves, arms): the sleeve follows the body
    private static void EngulfBody(int worms)
    {
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 13u, Vector3.zero);
        Vector3[][] seg =
        {
            new[] { new Vector3(0f, 0.95f, 0f), new Vector3(0f, 1.45f, 0f) }, new[] { new Vector3(0f, 1.5f, 0f), new Vector3(0f, 1.75f, 0f) },
            new[] { new Vector3(-0.1f, 0.5f, 0f), new Vector3(-0.1f, 0.95f, 0f) }, new[] { new Vector3(0.1f, 0.5f, 0f), new Vector3(0.1f, 0.95f, 0f) },
            new[] { new Vector3(-0.1f, 0.1f, 0f), new Vector3(-0.1f, 0.5f, 0f) }, new[] { new Vector3(0.1f, 0.1f, 0f), new Vector3(0.1f, 0.5f, 0f) },
            new[] { new Vector3(-0.25f, 1.1f, 0f), new Vector3(-0.25f, 1.4f, 0f) }, new[] { new Vector3(0.25f, 1.1f, 0f), new Vector3(0.25f, 1.4f, 0f) },
        };
        float[] rad = { 0.17f, 0.1f, 0.09f, 0.09f, 0.07f, 0.07f, 0.055f, 0.055f };
        for (int i = 0; i < 8; i++) m.Prims[i] = GpuPrim.Capsule(seg[i][0], seg[i][1], rad[i], 1f, 1f);
        m.Mode = GpuMassMode.Engulf;
        m.Engulf = 1f;
        m.AdhesivePrim = 0;
        m.AdhesiveCount = 8;
        m.ShellThickness = 0.02f;
        GpuWormHost.UploadEnvironment(m, 8, new Vector2(-m.GridExtent * 0.5f, -m.GridExtent * 0.5f), m.GridExtent / (WormSimConst.HeightN - 1));
        GpuWormHost.InitNow(m);
        GpuWormHost.StepNow(400);
        Vector4[] pos = Read(worms);
        Debug.Log($"SimCheck: engulf body: {CountNan(pos)} NaN nodes");
        Picture("engulf_body", m, 2.2f, 1.0f, 0.9f);
        Picture("engulf_body_close", m, 1.2f, 1.2f, 1.2f);
        GpuWormHost.RemoveMass(m);
    }

    // Area and orientation of what is on a vertical capsule: the cells (12 around x 12 up) with a node within 3 cm of the surface, the share of the worms with 5 or more nodes
    // on it that point up (axis tail to head rising by more than 0.3) or lie across (axis within 0.3 of the horizontal), and the mean number of nodes per covered cell
    // in a column of 1.2 cm (a layer of one to two worms holds about one to two).
    private static void SurfaceStats(Vector4[] pos, int worms, float cr, float height, out float area, out float up, out float flat, out float layers)
    {
        const int around = 12, rows = 12;
        var cell = new int[around * rows];
        int onBody = 0, pointing = 0, across = 0;
        for (int w = 0; w < worms; w++)
        {
            int near = 0;
            for (int i = 0; i < 8; i++)
            {
                Vector4 p = pos[w * 8 + i];
                if (p.y < 0.45f) continue;                 // the pile on the ground is not the layer on the body
                float y = Mathf.Clamp(p.y, cr, height - cr);
                float dist = new Vector3(p.x, p.y - y, p.z).magnitude - cr;
                if (dist > 0.03f) continue;
                near++;
                float ang = Mathf.Atan2(p.z, p.x) / (2f * Mathf.PI) + 0.5f;
                cell[Mathf.Clamp((int)(ang * around), 0, around - 1) * rows + Mathf.Clamp((int)(p.y / height * rows), 0, rows - 1)]++;
            }
            if (near < 5) continue;
            onBody++;
            Vector3 axis = new Vector3(pos[w * 8 + 7].x - pos[w * 8].x, pos[w * 8 + 7].y - pos[w * 8].y, pos[w * 8 + 7].z - pos[w * 8].z).normalized;
            if (axis.y > 0.3f) pointing++;
            else if (Mathf.Abs(axis.y) < 0.3f) across++;
        }
        int covered = 0, total = 0;
        foreach (int c in cell) if (c > 0) { covered++; total += c; }
        area = covered / (float)cell.Length;
        up = onBody > 0 ? pointing / (float)onBody : 0f;
        flat = onBody > 0 ? across / (float)onBody : 0f;
        float perLayer = (2f * Mathf.PI * (cr + 0.01f) / around) * (height / rows) / 0.0081f * 8f;     // nodes of one full layer of worms in a cell
        layers = covered > 0 ? total / (float)covered / perLayer : 0f;
        Debug.Log($"SimCheck: capsule surface: {onBody} worms on it, {covered} of {cell.Length} cells covered, {total} nodes within 3 cm");
    }

    // A rock (a bump of the height grid, 1 m high, 0.9 m wide) at the foot of a mass that stays on the ground: the worms must flow over the top and down the flanks, with a
    // pile at the foot; the centre of the mass does not move.
    private static void Drape(int worms)
    {
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 31u, Vector3.zero);
        int hn = WormSimConst.HeightN;
        float ext = m.GridExtent, sp = ext / (hn - 1);
        Vector2 min = new Vector2(-ext * 0.5f, -ext * 0.5f);
        const float rockX = 0.45f, rockR = 0.75f, rockH = 1.0f;
        for (int z = 0; z < hn; z++)
            for (int x = 0; x < hn; x++)
            {
                float dx = min.x + x * sp - rockX, dz = min.y + z * sp;
                float d2 = (dx * dx + dz * dz) / (rockR * rockR);
                m.Heights[z * hn + x] = rockH * Mathf.Sqrt(Mathf.Max(0f, 1f - d2));
            }
        GpuWormHost.UploadEnvironment(m, 0, min, sp);
        GpuWormHost.InitNow(m);
        GpuWormHost.StepNow(900);
        Vector4[] pos = Read(worms);
        int top = 0, flank = 0, foot = 0, ground = 0;
        float highest = 0f;
        foreach (Vector4 p in pos)
        {
            float d = new Vector2(p.x - rockX, p.z).magnitude;
            highest = Mathf.Max(highest, p.y);
            if (d < rockR * 0.45f && p.y > 0.7f) top++;
            else if (d < rockR * 1.05f && p.y > 0.15f) flank++;
            if (d >= rockR * 0.9f && d < rockR * 1.5f && p.y < 0.12f) foot++;
            if (p.y < 0.05f) ground++;
        }
        float n = pos.Length;
        Debug.Log($"SimCheck: drape: {top / n * 100f:0.0}% of the nodes on the top, {flank / n * 100f:0.0}% on the flanks, {foot / n * 100f:0.0}% at the foot, {ground / n * 100f:0.0}% on the ground; highest node {highest:0.00} m");
        Check("drape_covers_top_and_flanks", top > 0.01f * n && flank > 0.05f * n, $"top {top / n * 100f:0.0}%, flanks {flank / n * 100f:0.0}% (the worms go over the rock)");
        Check("drape_pile_at_the_foot", foot > 0.05f * n, $"{foot / n * 100f:0.0}% of the nodes at the foot (the worms also stay on the ground)");
        GpuWormHost.CameraProvider = null;
        Picture("drape", m, 3.2f, 1.2f, 0.4f);
        Picture("drape_close", m, 1.8f, 0.9f, 0.5f);
        GpuWormHost.RemoveMass(m);
    }

    // The scenario V14 on a block: a mass of n units walks toward a block 1.6 x h x 1.0 m, the environment re-captured every 8 steps as the game does (a height grid that holds a low
    // block as ground, depth maps for a high one), stops when its centre is within 0.2 m of the middle of the block, and 4 s later the nodes are counted (V14 CrossObstacle).
    private static void Cross(int worms, bool high)
    {
        string tag = (worms == 500 ? "n50" : "n200") + (high ? "_high" : "_low");
        float r = 0.26f * Mathf.Pow(worms / 100f, 0.36f);
        float h = high ? 2.0f : 0.5f * 0.45f * r;
        Vector3 bmin = new Vector3(-0.8f, 0f, -0.5f), bmax = new Vector3(0.8f, h, 0.5f);
        GpuMass m = Spawn(worms, r, 55u, new Vector3(-(0.8f + r + 2.5f), 0f, 0f));
        m.Heading = new Vector3(1f, 0f, 0f);
        m.ForceSimulated = true;
        CaptureBlock(m, bmin, bmax);
        GpuWormHost.InitNow(m);
        GpuWormHost.StepNow(120);
        float speed = 0f;
        bool stopped = false;
        int after = 0;
        for (int frame = 0; frame < 2400 && after < 30; frame++)
        {
            if (!stopped)
            {
                speed = Mathf.MoveTowards(speed, 1.2f, 2f * 8f / 60f);
                m.Center += new Vector3(speed * 8f / 60f, 0f, 0f);
                if (Mathf.Abs(m.Center.x) < 0.4f) { stopped = true; speed = 0f; }
            }
            else after++;
            m.Speed = speed;
            if (frame % 1 == 0) CaptureBlock(m, bmin, bmax);
            GpuWormHost.Tick(0f);
            GpuWormHost.StepNow(8);
        }
        Vector4[] pos = Read(worms);
        int total = pos.Length, onTop = 0, flank = 0, foot = 0, near = 0, nearSide = 0, farSide = 0, inside = 0;
        float upOn = Mathf.Min(0.3f, 0.5f * h), upFlank = Mathf.Min(0.1f, 0.25f * h);
        foreach (Vector4 p in pos)
        {
            float e = Mathf.Max(Mathf.Abs(p.x) / 0.8f, Mathf.Abs(p.z) / 0.5f);
            if (e < 1f && p.y > upOn) onTop++;
            if (e >= 0.6f && e < 1.2f && p.y > upFlank) flank++;
            if (e >= 1f && e < 1.8f && p.y < 0.15f) foot++;
            Vector3 d = new Vector3(Mathf.Max(Mathf.Abs(p.x) - 0.8f, 0f), Mathf.Max(p.y - h, Mathf.Max(-p.y, 0f)), Mathf.Max(Mathf.Abs(p.z) - 0.5f, 0f));
            float dist = d.magnitude;
            if (Mathf.Abs(p.x) < 0.8f - 0.004f && Mathf.Abs(p.z) < 0.5f - 0.004f && p.y < h - 0.004f) inside++;
            if (dist <= 0.05f) { near++; if (p.x < 0f) nearSide++; else farSide++; }
        }
        float pTop = 100f * onTop / total, pFlank = 100f * flank / total, pFoot = 100f * foot / total;
        Debug.Log($"SimCheck: cross {tag}: centre at x {m.Center.x:0.00}, {pTop:0.0}% over the block, {pFlank:0.0}% on the flanks, {pFoot:0.0}% at the foot, near {near} (near side {nearSide}, far side {farSide}), inside {inside}");
        if (!high)
        {
            Check($"cross_{tag}_on_the_block", pTop >= 25f, $"{pTop:0.0}% of the nodes over the block (>= 25%)");
            Check($"cross_{tag}_flanks", pFlank >= 15f, $"{pFlank:0.0}% (>= 15%)");
        }
        else
        {
            Check($"cross_{tag}_both_sides", nearSide >= 0.02f * total && farSide >= 0.02f * total, $"near side {nearSide}, far side {farSide} of {total} nodes (>= 2% each)");
        }
        Check($"cross_{tag}_not_inside", inside <= 0.02f * total, $"{inside} nodes inside the block");
        Picture("cross_" + tag, m, 3.2f, 1.2f, 0.4f);
        GpuWormHost.RemoveMass(m);
    }

    private static void CaptureBlock(GpuMass m, Vector3 bmin, Vector3 bmax)
    {
        int hn = WormSimConst.HeightN;
        float ext = m.GridExtent, sp = ext / (hn - 1);
        Vector2 min = new Vector2(m.Center.x - ext * 0.5f, m.Center.z - ext * 0.5f);
        bool low = bmax.y < 1.0f;                // CoverableHeight: a low block is part of the ground
        for (int a = 0; a < hn; a++)
            for (int b = 0; b < hn; b++)
            {
                float x = min.x + b * sp, z = min.y + a * sp;
                bool on = x >= bmin.x && x <= bmax.x && z >= bmin.z && z <= bmax.z;
                m.Heights[a * hn + b] = low && on ? bmax.y : 0f;
            }
        m.SideYMin = m.Center.y - 0.5f;
        m.SideYStep = (4f + 0.8f) / (hn - 1);
        m.SideEnabled = true;
        GpuMassParams pp = GpuWormHost.BuildParams(m, true);
        pp.GridRect = new Vector4(min.x - m.Origin.x, min.y - m.Origin.z, sp, 1f / sp);
        var floats = new float[WormSimConst.SideMaps * WormSimConst.SideMapSize];
        GpuSolidMaps.FillBox(floats, 0, pp, bmin, bmax);
        for (int i = 0; i < floats.Length; i++) m.Sides[i] = floats[i];
        GpuWormHost.UploadEnvironment(m, 0, min, sp);
    }

    private static int CountNan(Vector4[] pos)
    {
        int n = 0;
        foreach (Vector4 p in pos) if (float.IsNaN(p.x) || float.IsNaN(p.y) || float.IsNaN(p.z)) n++;
        return n;
    }

    private static float Coverage(Vector4[] pos, int worms, float cr, float height, float shell, out float topY, out int nodes)
    {
        const int bands = 12;
        var mark = new int[bands];
        topY = 0f;
        nodes = 0;
        for (int i = 0; i < worms * 8; i++)
        {
            Vector4 p = pos[i];
            float rad = new Vector2(p.x, p.z).magnitude;
            if (rad > cr + 0.012f + shell) continue;
            nodes++;
            int b = Mathf.Clamp((int)(p.y / height * bands), 0, bands - 1);
            if (rad < cr + 0.05f) { mark[b]++; topY = Mathf.Max(topY, p.y); }
        }
        int covered = 0;
        for (int b = 0; b < bands; b++) if (mark[b] >= 2) covered++;
        return covered / (float)bands;
    }

    // ------------------------------------------------------------------ free worms: ropes of the colony against the flipbooks

    private static readonly (MistWorms.Render.WormAnim anim, string file, int[] frames)[] FreeSets =
    {
        (MistWorms.Render.WormAnim.Crawl, "worm_crawl", new[] { 0, 3, 6, 9, 12 }),
        (MistWorms.Render.WormAnim.Idle, "worm_idle", new[] { 0, 2, 4, 6 }),
        (MistWorms.Render.WormAnim.Rear, "worm_rear", new[] { 0, 2, 3, 5 }),
        (MistWorms.Render.WormAnim.Strike, "worm_strike", new[] { 0, 1, 2, 3 }),
        (MistWorms.Render.WormAnim.Sleep, "worm_sleep", new[] { 0, 1, 2 }),
        (MistWorms.Render.WormAnim.Coil, "worm_coil", new[] { 0, 2, 4, 6, 8, 10 }),
    };

    private static Mesh LoadFlipbook(string file, int frame)
    {
        byte[] bytes = File.ReadAllBytes(Path.GetFullPath(Path.Combine("..", "..", "build", $"{file}_{frame:00}.glb")));
        MistWorms.Assets.GlbMeshData d = MistWorms.Assets.GlbParser.Parse(bytes, file);
        int vc = d.Positions.Length / 3;
        var pos = new Vector3[vc];
        var nrm = new Vector3[vc];
        var uv = new Vector2[vc];
        for (int i = 0; i < vc; i++)
        {
            pos[i] = new Vector3(-d.Positions[i * 3], d.Positions[i * 3 + 1], d.Positions[i * 3 + 2]);
            nrm[i] = new Vector3(-d.Normals[i * 3], d.Normals[i * 3 + 1], d.Normals[i * 3 + 2]);
            uv[i] = new Vector2(d.Uvs[i * 2], 1f - d.Uvs[i * 2 + 1]);
        }
        var tris = new int[d.Indices.Length];
        for (int i = 0; i < tris.Length; i += 3) { tris[i] = d.Indices[i]; tris[i + 1] = d.Indices[i + 2]; tris[i + 2] = d.Indices[i + 1]; }
        var mesh = new Mesh { name = file + frame };
        mesh.SetVertices(pos); mesh.SetNormals(nrm); mesh.SetUVs(0, uv); mesh.SetTriangles(tris, 0);
        mesh.RecalculateBounds();
        mesh.RecalculateTangents();
        return mesh;
    }

    // Each picture: the ropes (left) and the flipbook meshes (right) of one animation, one row per frame, heads to the right, the same camera. The nodes of a rope are the centre line of
    // its flipbook frame, so the two must overlap in shape; the difference to judge is the shading and the section.
    private static void FreeWorms()
    {
        if (!GpuWormHost.EnsureFree()) { Check("free_ropes_pool", false, "no room for the free ropes"); return; }
        Shader std = Shader.Find("Standard");
        var mat = new Material(std) { mainTexture = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Textures/worm_albedo.png") };
        mat.SetFloat("_Glossiness", 0.5f);
        int checkedPoses = 0, bad = 0;
        foreach (var set in FreeSets)
        {
            // numeric check: the nodes of the pose against the vertices of the flipbook mesh: every node lies within 3 mm of the axis of the mesh, in the order tail to head
            foreach (int f in set.frames)
            {
                Mesh fm = LoadFlipbook(set.file, f);
                GpuFreeWorms.Pose(set.anim, f, out Vector3[] nodes, out float[] sc);
                // the vertices of a .glb are not in the order of the topology: the boxes are compared. The centre line lies inside the box of the mesh and spans it to within the
                // radius of the body and the head (3 cm over the length)
                Bounds mb = fm.bounds;
                Vector3 nmin = nodes[0], nmax = nodes[0];
                foreach (Vector3 nd in nodes) { nmin = Vector3.Min(nmin, nd); nmax = Vector3.Max(nmax, nd); }
                float worst = 0f;
                for (int ax = 0; ax < 3; ax++)
                {
                    worst = Mathf.Max(worst, mb.min[ax] - nmin[ax], nmax[ax] - mb.max[ax]);
                    worst = Mathf.Max(worst, (mb.size[ax] - (nmax[ax] - nmin[ax])) - 0.03f);
                }
                if (worst > 0.005f) Debug.Log($"SimCheck: free pose {set.file}_{f:00}: nodes {nmin.ToString("0.000")} to {nmax.ToString("0.000")}, mesh {mb.min.ToString("0.000")} to {mb.max.ToString("0.000")}");
                checkedPoses++;
                if (worst > 0.005f) bad++;
                UnityEngine.Object.DestroyImmediate(fm);
            }
        }
        Check("free_poses_match_the_flipbooks", bad == 0, $"{checkedPoses} poses: the box of the 8 nodes inside the box of the flipbook mesh and within 3 cm of its span ({bad} not)");

        foreach (var set in FreeSets)
        {
            var go = new List<GameObject>();
            var camGo = new GameObject("FreeCam");
            Camera cam = camGo.AddComponent<Camera>();
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.25f, 0.28f, 0.32f);
            cam.renderingPath = RenderingPath.DeferredShading;
            cam.allowHDR = true;
            cam.nearClipPlane = 0.02f;
            cam.farClipPlane = 50f;
            int rows = set.frames.Length;
            float zMid = (rows - 1) * 0.07f * 0.5f;
            // the poses that rise (rear, strike, sleep) are seen from the side, the rows stacked in height; the others from above at an angle, the rows side by side
            bool side = set.anim == MistWorms.Render.WormAnim.Rear || set.anim == MistWorms.Render.WormAnim.Strike || set.anim == MistWorms.Render.WormAnim.Sleep;
            if (side)
            {
                camGo.transform.position = new Vector3(0.28f, rows * 0.045f, -1.1f);
                camGo.transform.LookAt(new Vector3(0.28f, rows * 0.045f, 0f));
                cam.fieldOfView = 25f;
            }
            else
            {
                camGo.transform.position = new Vector3(0.28f, 0.75f, zMid - 0.45f);
                camGo.transform.LookAt(new Vector3(0.28f, 0f, zMid));
            }
            var rt = new RenderTexture(1400, 800, 24);
            cam.targetTexture = rt;
            GpuWormHost.CameraProvider = () => cam;
            GpuWormHost.AutoStep = false;
            GpuWormHost.FreeBegin(cam.transform.position);
            for (int i = 0; i < rows; i++)
            {
                float z = side ? 0f : i * 0.07f, y = side ? i * 0.09f : 0f;
                Quaternion q = Quaternion.Euler(0f, 90f, 0f);     // heads to +x
                Matrix4x4 left = Matrix4x4.TRS(new Vector3(0f, y, z), q, Vector3.one);
                bool ok = GpuFreeWorms.TryAdd(set.anim, MistWorms.Render.WormLod.Lod0, set.frames[i], left, cam.transform.position);
                if (!ok) Check($"free_rope_taken_{set.file}_{set.frames[i]}", false, "the pool refused the rope");
                var obj = new GameObject("flip");
                obj.AddComponent<MeshFilter>().sharedMesh = LoadFlipbook(set.file, set.frames[i]);
                obj.AddComponent<MeshRenderer>().sharedMaterial = mat;
                obj.transform.SetPositionAndRotation(new Vector3(0.55f, y, z), q);
                go.Add(obj);
            }
            GpuWormHost.FreeEnd();
            GpuWormHost.Tick(0f);
            cam.Render();
            RenderTexture.active = rt;
            var tex = new Texture2D(rt.width, rt.height, TextureFormat.RGB24, false);
            tex.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
            tex.Apply();
            File.WriteAllBytes($"Logs/simcheck_free_{set.file}.png", tex.EncodeToPNG());
            Debug.Log($"SimCheck: picture free_{set.file}: {rows} ropes (left) against {rows} flipbooks (right), draw calls {GpuWormHost.DrawCalls}, ropes drawn {GpuWormHost.DrawnWorms}");
            Check($"free_ropes_drawn_{set.file}", GpuWormHost.DrawnWorms == rows, $"{GpuWormHost.DrawnWorms} ropes drawn of {rows}");
            RenderTexture.active = null;
            cam.targetTexture = null;
            UnityEngine.Object.DestroyImmediate(rt);
            UnityEngine.Object.DestroyImmediate(tex);
            UnityEngine.Object.DestroyImmediate(camGo);
            foreach (GameObject g in go) { UnityEngine.Object.DestroyImmediate(g.GetComponent<MeshFilter>().sharedMesh); UnityEngine.Object.DestroyImmediate(g); }
        }
        GpuWormHost.FreeBegin(Vector3.zero);
        GpuWormHost.FreeEnd();
    }

    // ------------------------------------------------------------------ 4. pictures

    private static void Pictures()
    {
        const int worms = 500;
        float r = Mathf.Pow(worms * 7.6e-5f / 0.5f / 0.94f, 1f / 3f);
        GpuMass m = Spawn(worms, r, 21u, Vector3.zero);
        GpuWormHost.InitNow(m);
        GpuWormHost.StepNow(240);
        TickAllocation(m);
        Picture("lod0_1m", m, 1.0f, 0.35f, 0.15f);
        Picture("lod0_3m", m, 3.0f, 1.0f, 0.2f);
        Picture("lod1_12m", m, 12f, 3f, 0.2f);
        Picture("lod2_30m", m, 30f, 6f, 0.2f);
        GpuWormHost.RemoveMass(m);
    }

    // The Tick of the host with the draws on (a camera that sees the mass, the simulation running, the lists drawn): nothing allocated in a steady window, the second of two
    // (the first absorbs what the runtime does once). Also the cost of the Tick with the draw submission, with and without the draws.
    private static void TickAllocation(GpuMass m)
    {
        var camGo = new GameObject("AllocCam");
        Camera cam = camGo.AddComponent<Camera>();
        camGo.transform.position = m.Center + new Vector3(2.4f, 1.0f, -1.8f);
        camGo.transform.LookAt(m.Center + Vector3.up * 0.2f);
        GpuWormHost.CameraProvider = () => cam;
        GpuWormHost.AutoStep = true;
        GpuWormHost.DrawEnabled = true;
        long[] rises = new long[2];
        for (int pass = 0; pass < 2; pass++)
        {
            for (int f = 0; f < 60; f++) GpuWormHost.Tick(1f / 60f);
            GpuWormHost.ResetStats();
            GpuWormHost.MeasureAlloc = true;
            for (int f = 0; f < 400; f++) GpuWormHost.Tick(1f / 60f);
            GpuWormHost.MeasureAlloc = false;
            rises[pass] = GpuWormHost.OwnAllocBytes;
        }
        Debug.Log($"SimCheck: host tick with the draws on: {GpuWormHost.AvgMs:0.0000} ms per frame, {GpuWormHost.DrawCalls} draw calls, allocation first window {rises[0]} bytes, second {rises[1]} bytes over 400 frames");
        Check("host_tick_no_allocation_with_draws", rises[1] == 0, $"{rises[1]} bytes over 400 frames of Tick with the camera on the mass and the draws submitted");
        GpuWormHost.AutoStep = false;
        UnityEngine.Object.DestroyImmediate(camGo);
    }

    private static GameObject s_ground, s_light;

    private static void Picture(string name, GpuMass m, float distance, float height, float lookHeight)
    {
        if (s_ground == null)
        {
            s_ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
            s_ground.transform.localScale = new Vector3(10f, 1f, 10f);
            s_ground.transform.position = new Vector3(0f, -0.001f, 0f);
            s_light = new GameObject("Light");
            Light l = s_light.AddComponent<Light>();
            l.type = LightType.Directional;
            l.shadows = LightShadows.Soft;
            l.transform.rotation = Quaternion.Euler(50f, -30f, 0f);
        }
        var camGo = new GameObject("Cam");
        Camera cam = camGo.AddComponent<Camera>();
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.25f, 0.28f, 0.32f);
        cam.renderingPath = RenderingPath.DeferredShading;
        cam.allowHDR = true;
        cam.nearClipPlane = 0.02f;
        cam.farClipPlane = 200f;
        camGo.transform.position = m.Center + new Vector3(distance * 0.8f, height, -distance * 0.6f);
        camGo.transform.LookAt(m.Center + Vector3.up * lookHeight);
        var rt = new RenderTexture(1280, 800, 24);
        cam.targetTexture = rt;

        GpuWormHost.CameraProvider = () => cam;
        GpuWormHost.AutoStep = false;
        GpuWormHost.Tick(0f);
        cam.Render();
        RenderTexture.active = rt;
        var tex = new Texture2D(rt.width, rt.height, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
        tex.Apply();
        Directory.CreateDirectory("Logs");
        File.WriteAllBytes($"Logs/simcheck_{name}.png", tex.EncodeToPNG());
        Color32[] px = tex.GetPixels32();
        int diff = 0;
        Color32 bg = cam.backgroundColor;
        foreach (Color32 c in px) if (Mathf.Abs(c.r - bg.r) + Mathf.Abs(c.g - bg.g) + Mathf.Abs(c.b - bg.b) > 30) diff++;
        Debug.Log($"SimCheck: picture {name}: draw calls {GpuWormHost.DrawCalls}, worms {GpuWormHost.DrawnWorms}, triangles {GpuWormHost.Triangles} (+{GpuWormHost.ShadowTriangles} shadow), {diff} pixels differ from the background");
        RenderTexture.active = null;
        cam.targetTexture = null;
        UnityEngine.Object.DestroyImmediate(rt);
        UnityEngine.Object.DestroyImmediate(tex);
        UnityEngine.Object.DestroyImmediate(camGo);
    }
}
